const vector = $json.data[0].embedding;
const literal = '[' + vector.join(',') + ']';
const sql = "SELECT p.numero_documento, p.primer_nombre, p.segundo_nombre, p.apellidos, p.fecha_nacimiento, 1 - (pe.embedding <=> '" + literal + "'::vector) AS similitud FROM persona_embeddings pe JOIN personas p ON p.numero_documento = pe.numero_documento ORDER BY pe.embedding <=> '" + literal + "'::vector LIMIT 5";
return [{ json: { sql } }];

const solicitud = $('Webhook').first().json.body;

const pregunta = solicitud.pregunta || '';
const sessionId = solicitud.session_id || '';
const usuarioId = solicitud.usuario_id || '';

if (typeof solicitud.pregunta !== 'string' || !solicitud.pregunta.trim()) {
  throw new Error('La pregunta no puede estar vacía');
}

// Personas recuperadas mediante búsqueda vectorial
const similares = $('Buscar similares').all().map(item => {
  const { similitud, ...persona } = item.json;
  return persona;
});

// Resultados de las consultas SQL de agregación
const agregados = $('Agregados').all().map(item => item.json);

// Persona más joven
const masJoven = agregados.find(
  item => item.tipo === 'mas_joven'
);

// Persona de mayor edad
const masMayor = agregados.find(
  item => item.tipo === 'mas_mayor'
);

function nombreCompleto(persona) {
  if (!persona) return null;

  return [
    persona.primer_nombre,
    persona.segundo_nombre,
    persona.apellidos
  ].filter(Boolean).join(' ');
}

// Cantidad real de personas registrada en PostgreSQL
const totalPersonas =
  agregados.length > 0 &&
  agregados[0].total_personas != null
    ? Number(agregados[0].total_personas)
    : null;

// Contexto estructurado para Ollama
const datosContexto = {
  total_personas: totalPersonas,

  nombre_mas_joven: nombreCompleto(masJoven),

  nombre_mas_mayor: nombreCompleto(masMayor),

  persona_mas_joven: masJoven || null,

  persona_mas_mayor: masMayor || null,

  similares
};

const contexto = JSON.stringify(datosContexto, null, 2);

return [{
  json: {
    pregunta,
    sessionId,
    usuarioId,
    total_personas: totalPersonas,
    contexto
  }
}];
